import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
const root = path.dirname(fileURLToPath(import.meta.url));
const md = fs.readFileSync(path.join(root,'docs/ecosystem/PHASE1_UC_SRS_TECHSPEC_MATRIX.md'),'utf8');
const sectionA = md.split('## 2.A')[1]?.split('## 2.B')[0] ?? '';
const codes = new Set();
for (const line of sectionA.split(/\n/)) {
  if (!/^\| \d+ \| \`/.test(line)) continue;
  codes.add(line.split('|')[2]?.trim().replace(/\`/g,''));
}
const raw = JSON.parse(fs.readFileSync(path.join(root,'docs/ecosystem/phase1-impl-status.json'),'utf8'));
let e2e=0, waived=0, gap=[];
for (const code of codes) {
  const st = raw.overrides[code]?.impl_status;
  if (st==='e2e_pass') e2e++;
  else if (st==='waived') waived++;
  else gap.push(code+':'+(st||'matrix'));
}
console.log('Block A:', codes.size);
console.log('e2e_pass:', e2e);
console.log('waived:', waived);
console.log('G2 total e2e+waived:', e2e+waived, '/ 104');
console.log('gaps:', gap.length, gap.slice(0,5).join(', '));
"

